CREATE OR REPLACE FUNCTION public.is_in_delivery_area(_lat numeric, _lng numeric)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path = public AS $f$
DECLARE
pts numeric[][] := ARRAY[[31.667185,-7.968653],[31.666533,-7.967703],[31.666640,-7.966520],[31.649223,-7.954171],[31.648880,-7.952905],[31.650114,-7.946579],[31.647977,-7.946552],[31.645944,-7.950027],[31.642102,-7.950600],[31.647192,-7.956672],[31.647750,-7.962872],[31.639361,-7.975344],[31.637342,-7.976051],[31.632374,-7.973922],[31.625100,-7.967102],[31.618200,-7.971413],[31.613800,-7.970197],[31.613000,-7.969496],[31.612630,-7.968158],[31.608551,-7.965148],[31.608533,-7.964059],[31.611098,-7.957601],[31.607396,-7.956059],[31.607175,-7.954751],[31.607999,-7.952901],[31.603747,-7.949475],[31.602280,-7.945170],[31.593830,-7.934707],[31.587005,-7.928922],[31.583290,-7.928506],[31.581891,-7.929207],[31.581822,-7.931982],[31.585184,-7.933685],[31.587510,-7.940963],[31.604482,-7.955358],[31.604574,-7.956530],[31.603453,-7.959107],[31.602395,-7.959951],[31.601504,-7.959700],[31.598165,-7.956562],[31.595739,-7.956552],[31.593685,-7.964109],[31.600330,-7.966112],[31.600804,-7.967311],[31.600233,-7.970952],[31.602437,-7.971873],[31.603007,-7.973347],[31.600207,-7.983721],[31.599168,-7.984657],[31.569431,-7.979504],[31.568972,-7.986594],[31.573338,-7.989468],[31.573912,-7.990676],[31.570655,-7.999054],[31.586638,-8.006448],[31.587495,-8.007902],[31.586900,-8.009228],[31.576786,-8.015635],[31.575666,-8.015601],[31.573713,-8.016893],[31.569605,-8.016844],[31.570729,-8.021356],[31.581985,-8.019807],[31.584039,-8.021114],[31.585719,-8.023089],[31.585942,-8.024396],[31.587216,-8.024544],[31.587906,-8.025828],[31.587355,-8.027200],[31.583699,-8.029729],[31.579845,-8.036068],[31.585442,-8.042228],[31.581853,-8.051108],[31.580767,-8.051836],[31.576597,-8.051131],[31.570396,-8.058758],[31.576552,-8.064016],[31.583260,-8.061654],[31.590699,-8.062798],[31.591694,-8.060854],[31.592666,-8.060410],[31.597600,-8.063398],[31.602361,-8.058926],[31.607669,-8.060073],[31.613571,-8.064894],[31.613672,-8.070998],[31.621864,-8.071095],[31.622690,-8.071564],[31.623071,-8.072548],[31.625757,-8.072965],[31.627584,-8.079176],[31.626802,-8.081499],[31.639296,-8.085246],[31.640866,-8.083837],[31.658798,-8.083698],[31.659549,-8.082076],[31.661980,-8.081013],[31.662346,-8.080419],[31.662801,-8.079668],[31.663250,-8.078912],[31.663693,-8.078152],[31.664131,-8.077387],[31.664563,-8.076618],[31.664989,-8.075844],[31.665409,-8.075066],[31.665823,-8.074284],[31.666232,-8.073498],[31.666635,-8.072707],[31.667032,-8.071912],[31.667423,-8.071114],[31.667807,-8.070311],[31.668186,-8.069504],[31.668559,-8.068694],[31.668926,-8.067880],[31.669287,-8.067062],[31.669641,-8.066240],[31.669989,-8.065415],[31.670332,-8.064586],[31.670668,-8.063754],[31.670997,-8.062919],[31.671321,-8.062080],[31.671638,-8.061238],[31.671949,-8.060392],[31.672254,-8.059544],[31.672552,-8.058692],[31.672844,-8.057837],[31.673129,-8.056980],[31.673409,-8.056119],[31.673681,-8.055256],[31.673947,-8.054390],[31.674207,-8.053521],[31.674460,-8.052650],[31.674707,-8.051776],[31.674947,-8.050900],[31.675181,-8.050021],[31.675408,-8.049140],[31.675628,-8.048256],[31.675842,-8.047371],[31.676049,-8.046483],[31.676250,-8.045593],[31.676444,-8.044701],[31.676631,-8.043807],[31.676812,-8.042911],[31.676985,-8.042014],[31.677153,-8.041114],[31.677313,-8.040213],[31.677467,-8.039311],[31.677614,-8.038407],[31.677754,-8.037501],[31.677887,-8.036594],[31.678014,-8.035686],[31.678134,-8.034776],[31.678247,-8.033865],[31.678353,-8.032953],[31.678452,-8.032041],[31.678545,-8.031127],[31.678631,-8.030212],[31.678710,-8.029296],[31.678782,-8.028380],[31.678847,-8.027462],[31.678905,-8.026545],[31.678957,-8.025626],[31.679002,-8.024707],[31.679039,-8.023788],[31.679070,-8.022869],[31.679094,-8.021949],[31.679111,-8.021029],[31.679122,-8.020108],[31.679125,-8.019188],[31.679122,-8.018268],[31.679111,-8.017347],[31.679094,-8.016427],[31.679070,-8.015507],[31.679039,-8.014588],[31.679002,-8.013669],[31.678957,-8.012750],[31.678905,-8.011831],[31.678847,-8.010914],[31.678782,-8.009996],[31.678710,-8.009080],[31.678631,-8.008164],[31.678545,-8.007249],[31.678452,-8.006335],[31.678353,-8.005423],[31.678247,-8.004511],[31.678134,-8.003600],[31.678014,-8.002690],[31.677887,-8.001782],[31.677754,-8.000875],[31.677614,-7.999969],[31.677467,-7.999065],[31.677313,-7.998163],[31.677153,-7.997262],[31.676985,-7.996362],[31.676812,-7.995465],[31.676631,-7.994569],[31.676444,-7.993675],[31.676250,-7.992783],[31.676049,-7.991893],[31.675842,-7.991005],[31.675628,-7.990120],[31.675408,-7.989236],[31.675181,-7.988355],[31.674947,-7.987476],[31.674707,-7.986600],[31.674460,-7.985726],[31.674207,-7.984855],[31.673947,-7.983986],[31.673681,-7.983120],[31.673409,-7.982257],[31.673129,-7.981396],[31.672844,-7.980539],[31.672552,-7.979684],[31.672254,-7.978832],[31.671949,-7.977984],[31.671638,-7.977138],[31.671321,-7.976296],[31.670997,-7.975457],[31.670668,-7.974622],[31.670332,-7.973790],[31.669989,-7.972961],[31.669641,-7.972136],[31.669287,-7.971314],[31.668926,-7.970496],[31.668559,-7.969682],[31.668186,-7.968872],[31.668149,-7.968793],[31.667185,-7.968653]];
n int := array_length(pts,1); i int; j int; inside boolean := false; cross_value numeric;
BEGIN
 IF _lat IS NULL OR _lng IS NULL OR _lat::text IN ('NaN','Infinity','-Infinity') OR _lng::text IN ('NaN','Infinity','-Infinity') OR abs(_lat)>90 OR abs(_lng)>180 THEN RETURN false; END IF;
 j := n;
 FOR i IN 1..n LOOP
  cross_value := (_lng-pts[i][2])*(pts[j][1]-pts[i][1])-(_lat-pts[i][1])*(pts[j][2]-pts[i][2]);
  IF abs(cross_value)<=0.000000000001 AND _lng BETWEEN least(pts[i][2],pts[j][2]) AND greatest(pts[i][2],pts[j][2]) AND _lat BETWEEN least(pts[i][1],pts[j][1]) AND greatest(pts[i][1],pts[j][1]) THEN RETURN true; END IF;
  IF (pts[i][1]>_lat)<>(pts[j][1]>_lat) THEN
   IF _lng<(pts[j][2]-pts[i][2])*(_lat-pts[i][1])/(pts[j][1]-pts[i][1])+pts[i][2] THEN inside := NOT inside; END IF;
  END IF;
  j := i;
 END LOOP;
 RETURN inside;
END $f$;
REVOKE ALL ON FUNCTION public.is_in_delivery_area(numeric,numeric) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_in_delivery_area(numeric,numeric) TO authenticated, service_role;
COMMENT ON FUNCTION public.is_in_delivery_area(numeric,numeric) IS 'Exact Glovo store delivery polygon (228 coordinates), MAR_delivery_area_polygon.kml supplied 2026-11-25; inclusive boundary, not the full Marrakech zone.';
DO $d$
DECLARE def text; old_match text := 'AND v_distance >= coalesce(z.min_radius_km, 0) AND v_distance <= z.radius_km ORDER BY z.radius_km ASC LIMIT 1;';
BEGIN
 SELECT pg_get_functiondef(p.oid) INTO def FROM pg_proc p WHERE p.proname='create_customer_order' AND p.pronamespace='public'::regnamespace;
 IF def IS NULL OR position('is_in_delivery_area' in def)=0 OR position(old_match in def)=0 THEN RAISE EXCEPTION 'Order coverage guard or tariff selector not found'; END IF;
 def := replace(def, old_match, 'AND v_distance >= coalesce(z.min_radius_km, 0) AND (v_distance <= z.radius_km OR (z.radius_km = (SELECT max(last_zone.radius_km) FROM public.delivery_zones last_zone WHERE last_zone.is_active = true) AND public.is_in_delivery_area(v_address.latitude, v_address.longitude))) ORDER BY z.radius_km ASC LIMIT 1;');
 EXECUTE def;
END $d$;